import{_ as e,o,c as r,a}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const h=JSON.parse('{"title":"Approximate — алго-трейдер с ньюс-анализом","description":"Кейс Approximate: пайплайн данных, ансамбль LightGBM и XGBoost, риск-гейты и kill switch. Публичное исследование AlgoPack и MOEX, стоимость займа акций 25% вместо ожидаемых 17%.","frontmatter":{"site":"pro","title":"Approximate — алго-трейдер с ньюс-анализом","description":"Кейс Approximate: пайплайн данных, ансамбль LightGBM и XGBoost, риск-гейты и kill switch. Публичное исследование AlgoPack и MOEX, стоимость займа акций 25% вместо ожидаемых 17%.","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/work/approximate"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Approximate — алго-трейдер с ньюс-анализом"}],["meta",{"property":"og:description","content":"Кейс Approximate: пайплайн данных, ансамбль LightGBM и XGBoost, риск-гейты и kill switch. Публичное исследование AlgoPack и MOEX, стоимость займа акций 25% вместо ожидаемых 17%."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/work/approximate"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Approximate — алго-трейдер с ньюс-анализом"}],["meta",{"name":"twitter:description","content":"Кейс Approximate: пайплайн данных, ансамбль LightGBM и XGBoost, риск-гейты и kill switch. Публичное исследование AlgoPack и MOEX, стоимость займа акций 25% вместо ожидаемых 17%."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"work/approximate.md","filePath":"work/approximate.md"}'),i={name:"work/approximate.md"};function n(l,t,p,s,g,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="approximate-—-алго-треидер-с-ньюс-анализом" tabindex="-1">Approximate — алго-трейдер с ньюс-анализом <a class="header-anchor" href="#approximate-—-алго-треидер-с-ньюс-анализом" aria-label="Permalink to &quot;Approximate — алго-трейдер с ньюс-анализом&quot;">​</a></h1><p><strong>Задача.</strong> Большой объём рыночных новостей руками не разобрать. Нужен сигнал: что покупать, что продавать и когда лучше не делать ничего.</p><p><strong>Ограничения.</strong> Ошибка стоит денег. Модель обязана уметь молчать, а система — выключаться. Публичных данных мало, качество разметки низкое.</p><h2 id="что-сделал" tabindex="-1">Что сделал <a class="header-anchor" href="#что-сделал" aria-label="Permalink to &quot;Что сделал&quot;">​</a></h2><p>Пайплайн от данных до сделки:</p><ol><li><strong>Сбор данных</strong> — рыночные котировки и новостной поток.</li><li><strong>Признаки</strong> — технические и новостные, с приведением к единому времени.</li><li><strong>Ансамбль</strong> — LightGBM, XGBoost и логистическая регрессия.</li><li><strong>Порог</strong> — решение принимается только за пределами <code>0.60</code> / <code>0.40</code>.</li><li><strong>Вето</strong> — ньюс-вето, детектор инцидентов, риск-гейт.</li><li><strong>Исполнение и алерты</strong> — сделка или сообщение в Telegram.</li></ol><p>Отдельно сделал <strong>kill switch</strong> и песочный профиль, который читает вероятности из таблицы скоринга. Это позволяет прогонять логику без живой модели.</p><p><strong>Новостной анализ</strong> вынесен в отдельные команды: сбор, разметка, обучение классификатора. LLM убрана из критического пути — она даёт контекст, но не голосует.</p><h2 id="доказательство" tabindex="-1">Доказательство <a class="header-anchor" href="#доказательство" aria-label="Permalink to &quot;Доказательство&quot;">​</a></h2><p>Исследование по AlgoPack и MOEX опубликовано и прошло рецензирование. Во второй версии закрыл восемь «белых пятен», которые сам же и обозначил. Главное: стоимость займа акций оказалась <strong>25% годовых, а не 17%</strong>, как предполагалось в первой версии. Это меняет оценку стратегий с короткими позициями.</p><ul><li>Код: <a href="https://github.com/alterfo/moex-trader" target="_blank" rel="noreferrer">github.com/alterfo/moex-trader</a></li><li>Исследование: <a href="https://zenodo.org/records/24111519" target="_blank" rel="noreferrer">zenodo.org/records/24111519</a></li></ul><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Сравнение песочницы и живой модели на одном периоде, с отчётом по расхождению.</li><li>Мониторинг деградации: алерт, когда распределение признаков уезжает.</li><li>Ограничение просадки как отдельный контур, а не порог в модели.</li></ul>',13)])])}const d=e(i,[["render",n]]);export{h as __pageData,d as default};
